SELECT b.id, d.day, '{"eighty_six": [{"name": "Dom Pérignon 2015", "status": "out"}, {"name": "Hennessy XO (Bottle Service)", "status": "limited", "left": 2}, {"name": "Yuzu Sour (Bar)", "status": "limited"}], "specials": [{"name": "Table A Package", "price": "NT$12,000 min"}, {"name": "Friday Upgrade — free upgrade to XO on 3+ bottles", "price": ""}], "shift_notes": "Tables S1, S2, A1 pre-booked. Guest list open until 11pm — confirm count with door at 10:30pm. DJ set change at 12:30am. Security briefing at 9:30pm — strict dress code, no sneakers. VIP host on floor from 10pm.", "reservations": [{"time": "22:00", "pax": 6, "table": "S1", "title": "Wu Kai-Ming", "notes": "VVIP · Host personally confirmed · Moët Rosé on arrival · No photos", "tags": [{"kind": "vip", "label": "VVIP"}], "status": "confirmed"}, {"time": "22:30", "pax": 4, "table": "A1", "title": "Huang Yi-Fan Group", "notes": "Birthday group · 2× Hennessy XO pre-ordered · Sparkler service at 12am", "tags": [{"kind": "birthday", "label": "BIRTHDAY"}], "status": "confirmed"}, {"time": "23:00", "pax": 8, "table": "S2", "title": "Corporate Booking — Atlas Capital", "notes": "Client entertainment · Invoice billing pre-approved · Escort from lobby", "tags": [{"kind": "event", "label": "EVENT"}], "status": "confirmed"}, {"time": "23:30", "pax": 2, "table": "B3", "title": "Lin Zhe-Han", "notes": "VIP regular · Usual table · Yuzu Sour on arrival", "tags": [{"kind": "vip", "label": "VIP"}], "status": "confirmed"}]}', (SELECT id FROM users WHERE name = 'Gerald Moss')
